-- High-granularity timeline events for testing timeline chart visualizations.
-- Events span ~2.5 hours at second/minute granularity, simulating a deployment
-- incident across multiple microservices.
--
-- Phases:
--   14:00-14:34  Normal operations (steady, low latencies)
--   14:35-14:44  Rolling deploy of payment-service v2.1.0
--   14:45-15:00  Error spike, alerts triggered, on-call investigation
--   15:01-15:16  Rollback, mixed success/failure
--   15:17-16:30  Recovery, return to normal, gradual traffic increase

CREATE TABLE IF NOT EXISTS analytics.timeline_events (
    timestamp     DateTime,
    service       LowCardinality(String),
    event_type    LowCardinality(String),
    component     String,
    value         Float32,
    status        LowCardinality(String),
    region        LowCardinality(String),
    message       String
) ENGINE = MergeTree()
ORDER BY (timestamp, service, event_type);

